  `outside_site` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'åº“å¤–ç«™ç‚¹',
  `is_empty` int DEFAULT '1' COMMENT '是否为空托（0:否 1:是）',
  `is_bound` int DEFAULT '0' COMMENT '是否已绑定物料（0:否 1:是）',
