  KEY `idx_outside_site` (`outside_site`)
) ENGINE=InnoDB AUTO_INCREMENT=1998574183371882816 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='托盘表';
